    float* const AsBase = smem;                       // 3 stages of BM x LDA
    float* const BsBase = smem + 3 * BM * LDA;        // 3 stages of BK x LDB
    const int bx = blockIdx.x;
    const int by = blockIdx.y;
    const int tid = threadIdx.x;        // 0..255
