            As[swz_a(ml, kl)] = v;
        }
        #pragma unroll
        for (int r = 0; r < 2; ++r) {
            const int idx = tid + r * 256;
            const int kl = idx >> 5;
            const int nl = (idx & 31) * 4;
            const int gk = k0 + kl;
            const int gn = bx * BN + nl;
            float v0 = 0.0f, v1 = 0.0f, v2 = 0.0f, v3 = 0.0f;
            if (gk < N) {
                if (gn + 0 < N) v0 = B[(long long)gk * N + gn + 0];
                if (gn + 1 < N) v1 = B[(long long)gk * N + gn + 1];
                if (gn + 2 < N) v2 = B[(long long)gk * N + gn + 2];
                if (gn + 3 < N) v3 = B[(long long)gk * N + gn + 3];
            }
            const int sb = swz_b(kl, nl);
            Bs[sb + 0] = v0;
            Bs[sb + 1] = v1;
            Bs[sb + 2] = v2;
            Bs[sb + 3] = v3;
        }
    }
}
// 128x128 CTA tile, 8 warps arranged 2x4, each warp owns a 64x32 tile
// computed with tensor-core mma.m16n8k8 (tf32 inputs, fp32 accumulate).
// Three-stage cp.async pipeline (deep prefetch) to hide global-memory latency.
__global__ __launch_bounds__(256, 3) void sgemm_square_kernel(
    const float* __restrict__ A,
    const float* __restrict__ B,
    float* __restrict__ C,
    int N)
{
    extern __shared__ __align__(16) float smem[];
