    float* const BsBase = smem + 2 * BM * LDA;        // 2 stages of BK x LDB
    const int bx = blockIdx.x;
    const int by = blockIdx.y;
    const int tid = threadIdx.x;        // 0..255
    const int warp = tid >> 5;          // 0..7
    const int lane = tid & 31;          // 0..31
    const int wm = (warp >> 2) * 64;    // warp tile row base (0 or 64)
    const int wn = (warp & 3) * 32;     // warp tile col base (0, 32, 64, 96)
    const int gid = lane >> 2;          // 0..7
    const int tig = lane & 3;           // 0..3
    float acc[4][4][4];
    #pragma unroll
    for (int i = 0; i < 4; ++i) {
        #pragma unroll
        for (int j = 0; j < 4; ++j) {
            #pragma unroll
            for (int v = 0; v < 4; ++v) {
                acc[i][j][v] = 0.0f;
            }
        }
    }
