    load_ab_tile(A, B, AsBase, BsBase, N, 0, bx, by, tid, vec_ok);
    cp_async_commit();
    int stage = 0;
    int stage = 0;
    for (int t = 0; t < numTiles; ++t) {
        // Prefetch K-tile t+1 into the free second stage while computing the current one.
        // The commit is issued unconditionally so the outstanding-group count stays in sync.
        if (t + 1 < numTiles) {
            const int ns = stage ^ 1;
            load_ab_tile(A, B, AsBase + ns * BM * LDA, BsBase + ns * BK * LDB, N, (t + 1) * BK, bx, by, tid, vec_ok);
        }
        cp_async_commit();
        cp_async_wait<1>();
        __syncthreads();
        const float* Asc = AsBase + stage * BM * LDA;
        const float* Bsc = BsBase + stage * BK * LDB;
        #pragma unroll
        for (int kk = 0; kk < BK; kk += 8) {
            unsigned afr[4][4];
            unsigned bfr[4][2];
            #pragma unroll
            #pragma unroll
            for (int mi = 0; mi < 4; ++mi) {
                const int m0 = wm + mi * 16 + gid;
                afr[mi][0] = f2tf32(Asc[swz_a(m0, kk + tig)]);
                afr[mi][1] = f2tf32(Asc[swz_a(m0 + 8, kk + tig)]);
                afr[mi][2] = f2tf32(Asc[swz_a(m0, kk + tig + 4)]);
                afr[mi][3] = f2tf32(Asc[swz_a(m0 + 8, kk + tig + 4)]);
