                const int n0 = wn + ni * 8 + gid;
                bfr[ni][0] = f2tf32(Bsc[swz_b(kk + tig, n0)]);
                bfr[ni][1] = f2tf32(Bsc[swz_b(kk + tig + 4, n0)]);
            }
