            for (int mi = 0; mi < 4; ++mi) {
                #pragma unroll
                for (int ni = 0; ni < 4; ++ni) {
                    mma_tf32_16x8x8(acc[mi][ni], afr[mi], bfr[ni]);
                }
            }
        }
        __syncthreads();
        stage ^= 1;
    }
    #pragma unroll
    for (int mi = 0; mi < 4; ++mi) {
        const int r0 = by * BM + wm + mi * 16 + gid;
