        for (int ni = 0; ni < 4; ++ni) {
            const int c0 = bx * BN + wn + ni * 8 + tig * 2;
            if (r0 < N) {
                if (c0 < N)     C[(long long)r0 * N + c0] = acc[mi][ni][0];
