                    mma_tf32_16x8x8(acc[mi][ni], afr[mi], bfr[ni]);
                }
            }
        }
        __syncthreads();
        stage = (stage == 2) ? 0 : (stage + 1);
    }
    #pragma unroll
    for (int mi = 0; mi < 4; ++mi) {
        const int r0 = by * BM + wm + mi * 16 + gid;
        #pragma unroll
        for (int ni = 0; ni < 4; ++ni) {
            const int c0 = bx * BN + wn + ni * 8 + tig * 2;
            if (r0 < N) {
                if (c0 < N)     C[(long long)r0 * N + c0] = acc[mi][ni][0];
                if (c0 + 1 < N) C[(long long)r0 * N + c0 + 1] = acc[mi][ni][1];
            }
            if (r0 + 8 < N) {
                if (c0 < N)     C[(long long)(r0 + 8) * N + c0] = acc[mi][ni][2];
                if (c0 + 1 < N) C[(long long)(r0 + 8) * N + c0 + 1] = acc[mi][ni][3];
            }
        }
    }
}
torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B)
{
    TORCH_CHECK(A.is_cuda(), "A must be a CUDA tensor");
