        smem_attr_set = true;
    }
    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    sgemm_square_kernel<<<grid, block, SMEM_BYTES, stream>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
